#!/usr/bin/env python3
"""Ports the generated specification tests of pulldown-cmark 0.10.3 to Go.

The crate's build script writes one Rust test for each example of the
CommonMark specification and of the extension specifications into
tests/suite/*.rs. Every test has the same shape:

    #[test]
    fn spec_test_1() {
        let original = r##"..."##;
        let expected = r##"..."##;

        test_markdown_html(original, expected, false, false, false);
    }

This script rewrites each of those files as it_lib_suite_<name>_test.go, one
Go test for each Rust test, with the names the port's rules give them
(TestItLibSuite<Name>_<rust name>).

Usage, from the repository root:

    python3 go/crates/pulldowncmark/testdata/port_suite.py \
        ~/.cargo/registry/src/*/pulldown-cmark-0.10.3/tests/suite \
        go/crates/pulldowncmark
"""
import pathlib
import re
import sys

TEST = re.compile(
    r'#\[test\]\n'
    r'fn (\w+)\(\) \{\n'
    r'    let original = r##"(.*?)"##;\n'
    r'    let expected = r##"(.*?)"##;\n'
    r'\n'
    r'    test_markdown_html\(original, expected, (true|false), (true|false), (true|false)\);\n'
    r'\}\n',
    re.S,
)


def pascal(name: str) -> str:
    return "".join(part[:1].upper() + part[1:].lower() for part in name.split("_"))


def quote_piece(piece: str) -> str:
    out = ['"']
    for ch in piece:
        cp = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\t":
            out.append("\\t")
        elif ch == "\r":
            out.append("\\r")
        elif cp < 0x20 or cp == 0x7F:
            out.append("\\x%02x" % cp)
        elif cp < 0x7F or ch.isprintable():
            out.append(ch)
        elif cp <= 0xFFFF:
            out.append("\\u%04x" % cp)
        else:
            out.append("\\U%08x" % cp)
    out.append('"')
    return "".join(out)


def quote(text: str) -> str:
    """A Go string expression for text, one source line for each line of text."""
    if text == "":
        return '""'
    pieces = text.split("\n")
    lines = [piece + "\n" for piece in pieces[:-1]]
    if pieces[-1] != "":
        lines.append(pieces[-1])
    return " +\n\t\t".join(quote_piece(line) for line in lines)


def port(source: pathlib.Path, target_dir: pathlib.Path) -> int:
    text = source.read_text(encoding="utf-8")
    tests = TEST.findall(text)
    declared = text.count("#[test]")
    if len(tests) != declared:
        raise SystemExit(f"{source}: recognised {len(tests)} of {declared} tests")
    stem = source.stem
    prefix = "TestItLibSuite" + pascal(stem)
    out = [
        f"// Port of pulldown-cmark 0.10.3 tests/suite/{source.name}",
        "",
        "// Code generated by testdata/port_suite.py from the Rust file; DO NOT EDIT.",
        "",
        "// This file is auto-generated by the build script",
        "// Please, do not modify it manually",
        "",
        "package pulldowncmark",
        "",
        'import "testing"',
    ]
    for name, original, expected, smart, metadata, old_footnotes in tests:
        out += [
            "",
            f"func {prefix}_{name}(t *testing.T) {{",
            f"\toriginal := {quote(original)}",
            f"\texpected := {quote(expected)}",
            "",
            f"\ttestMarkdownHtml(t, original, expected, {smart}, {metadata}, {old_footnotes})",
            "}",
        ]
    out.append("")
    (target_dir / f"it_lib_suite_{stem}_test.go").write_text("\n".join(out), encoding="utf-8")
    return len(tests)


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    suite, target_dir = pathlib.Path(argv[1]), pathlib.Path(argv[2])
    total = 0
    for source in sorted(suite.glob("*.rs")):
        if source.name == "mod.rs":
            continue
        total += port(source, target_dir)
    print(f"ported {total} tests")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
